def max_number(nums1, nums2, k):
    def best_subsequence(nums, t):
        stack = []
        drop = len(nums) - t
        for num in nums:
            while stack and drop > 0 and stack[-1] < num:
                stack.pop()
                drop -= 1
            stack.append(num)
        return stack[:t]

    def merge(a, b):
        result = []
        i = j = 0
        while i < len(a) or j < len(b):
            if a[i:] > b[j:]:
                result.append(a[i])
                i += 1
            else:
                result.append(b[j])
                j += 1
        return result

    m, n = len(nums1), len(nums2)
    best = []
    for i in range(max(0, k - n), min(k, m) + 1):
        candidate = merge(best_subsequence(nums1, i), best_subsequence(nums2, k - i))
        if candidate > best:
            best = candidate
    return best

